const b=$input.first().json.body||{};
if(b.secret!=='sv-mail-2026-09-17-Kq7'){throw new Error('bad secret');}
if(b.mb!=='4'){throw new Error('mailbox 4 only');}
if(!/^[0-9a-f]{16}$/.test(b.thread_id||'')){throw new Error('bad thread id');}
if(!b.html||!b.expect_last_from){throw new Error('missing html / expect_last_from');}
const a=b.atts;
if(!Array.isArray(a)||!a.length){throw new Error('need atts[] with filename, mime, b64');}
if(a.length>5){throw new Error('max 5 attachments');}
let total=0;
for(const x of a){
  if(!x.filename||!x.mime||!x.b64){throw new Error('each att needs filename, mime, b64');}
  if(/[\r\n"]/.test(x.filename)){throw new Error('bad filename: '+x.filename);}
  const n=Buffer.from(String(x.b64).replace(/\s+/g,''),'base64').length;
  if(!n){throw new Error('empty attachment: '+x.filename);}
  total+=n;
}
