return [{json:b}];

const p=$('Check').first().json;const m=$input.first().json;
function hdr(x,n){const h=((x.payload||{}).headers||[]).find(y=>String(y.name).toLowerCase()===n);return h?String(h.value):'';}
const addrs=v=>(String(v).match(/[A-Za-z0-9._%+'-]+@[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+/g)||[]).map(x=>x.toLowerCase());
const OURS=/@sidanaventures\.com$/;
const msgs=m.messages||[];
if(m.id!==p.thread_id||!msgs.length){throw new Error('thread not found in mailbox 4');}
const first=msgs[0],last=msgs[msgs.length-1];
if(!p.allow_external_start&&!/@sidanaventures\.com/i.test(hdr(first,'from'))){throw new Error('thread not started by us');}
const lf=addrs(hdr(last,'from'))[0]||'';
if(lf!==p.expect_last_from.toLowerCase()){throw new Error('latest message is from '+lf+', expected '+p.expect_last_from+' - someone replied since; not sending');}
const onThread=new Set();msgs.forEach(x=>['from','to','cc'].forEach(k=>addrs(hdr(x,k)).forEach(a=>onThread.add(a))));
let to=[];
if(Array.isArray(p.to_only)&&p.to_only.length){to=p.to_only.map(a=>String(a).trim().toLowerCase());const bad=to.filter(a=>!onThread.has(a));if(bad.length){throw new Error('not on thread: '+bad.join(', '));}}
else{to=[...onThread].filter(a=>!OURS.test(a)&&!/calendar|calendly|noreply|no-reply|otter|fireflies/.test(a));}
if(!to.length){throw new Error('no recipients');}
const subj='Re: '+hdr(first,'subject').replace(/^\s*(re|fwd?|fw)\s*:\s*/i,'');
const msgId=hdr(last,'message-id');const refs=(hdr(last,'references')+' '+msgId).trim();
const wrap=s=>String(s).replace(/(.{76})/g,'$1\r\n');
const B='sv_'+Date.now().toString(36)+'_bnd';
const parts=['--'+B,'Content-Type: text/html; charset="UTF-8"','Content-Transfer-Encoding: base64','',wrap(Buffer.from(p.html,'utf8').toString('base64'))];
const report=[];
for(const a of p.atts){
  const clean=String(a.b64).replace(/\s+/g,'');
  const bytes=Buffer.from(clean,'base64').length;
  report.push(a.filename+' '+(bytes/1024).toFixed(0)+'KB');
  parts.push('--'+B,'Content-Type: '+a.mime+'; name="'+a.filename+'"','Content-Disposition: attachment; filename="'+a.filename+'"','Content-Transfer-Encoding: base64','',wrap(clean));
}
parts.push('--'+B+'--','');
const mime=['From: Akansha SV <akansha@sidanaventures.com>','To: '+to.join(', '),(p.cc?'Cc: '+p.cc:'X-Sidana: 1'),'Subject: =?UTF-8?B?'+Buffer.from(subj,'utf8').toString('base64')+'?=','In-Reply-To: '+msgId,'References: '+refs,'MIME-Version: 1.0','Content-Type: multipart/mixed; boundary="'+B+'"',''].concat(parts).join('\r\n');
const raw=Buffer.from(mime,'utf8').toString('base64').replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
if(p.dry!==false){throw new Error('DRY OK | to='+to.join(', ')+' | cc='+(p.cc||'')+' | subject='+subj+' | atts='+report.join(' + ')+' | raw='+(raw.length/1048576).toFixed(2)+'MB | msgs='+msgs.length+' | first_from='+hdr(first,'from'));}
return [{json:{to:to.join(', '),subject:subj,raw:raw,threadId:p.thread_id,atts:report.join(' + ')}}];

